#!/usr/bin/env node
/**
 * Generate the registration captcha widgets for the app: `node src/features/auth/captcha/vendor/build.mjs`.
 *
 * The web client bundles three of its four captcha widgets from npm (altcha, @cap.js/widget,
 * @friendlycaptcha/sdk) so that registering contacts nothing but the instance (and, for
 * Friendly Captcha, the provider the operator chose). None of them can run in Hermes - they
 * are DOM custom elements with Web Workers and WASM - so the app runs them in a WebView
 * (../CaptchaWebView.tsx), and this script embeds the same packages, at the versions the
 * web client pins, as strings the page can inline. Turnstile is not here: it only exists as
 * Cloudflare's hosted script, which the web loads from Cloudflare as well.
 *
 * Emits scripts.js (+ scripts.d.ts) next to this file. Packages are looked up in, in order:
 * $CAPTCHA_VENDOR_NODE_MODULES, ./node_modules, web/node_modules, ../web.strafe.chat/node_modules.
 * Re-run after the web client bumps one of them.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..', '..', '..', '..');

const PACKAGES = [
  { name: 'altcha', file: 'dist/main/altcha.i18n.umd.min.cjs', exportName: 'ALTCHA_SCRIPT' },
  { name: '@cap.js/widget', file: 'cap.min.js', exportName: 'CAP_SCRIPT' },
  { name: '@friendlycaptcha/sdk', file: 'site.min.js', exportName: 'FRIENDLY_SCRIPT' },
];

const SEARCH = [
  process.env.CAPTCHA_VENDOR_NODE_MODULES,
  path.join(ROOT, 'node_modules'),
  path.join(ROOT, 'web', 'node_modules'),
  path.join(ROOT, '..', 'web.strafe.chat', 'node_modules'),
].filter(Boolean);

const webDeps = JSON.parse(readFileSync(path.join(ROOT, 'web', 'package.json'), 'utf8')).dependencies ?? {};
const major = (v) => String(v).replace(/^[^\d]*/, '').split('.')[0];

function locate(name) {
  for (const dir of SEARCH) {
    const pkgDir = path.join(dir, name);
    if (existsSync(path.join(pkgDir, 'package.json'))) return pkgDir;
  }
  return null;
}

/** Safe to drop inside <script>...</script> in an HTML string. */
function inlineSafe(code) {
  return code.replace(/<\/script/gi, '<\\/script').replace(/<!--/g, '<\\!--');
}

const out = [];
const dts = [];
const header = [];
for (const p of PACKAGES) {
  const dir = locate(p.name);
  if (!dir) {
    console.error(`${p.name} is not installed (looked in ${SEARCH.join(', ')}).`);
    process.exit(1);
  }
  const pkg = JSON.parse(readFileSync(path.join(dir, 'package.json'), 'utf8'));
  const wanted = webDeps[p.name];
  if (wanted && major(wanted) !== major(pkg.version)) {
    console.error(`${p.name} ${pkg.version} does not match the web client's ${wanted}.`);
    process.exit(1);
  }
  const code = readFileSync(path.join(dir, p.file), 'utf8');
  header.push(`${p.name}@${pkg.version} (${pkg.license ?? 'see package'})`);
  out.push(`/** ${p.name}@${pkg.version}, ${p.file}. License: ${pkg.license ?? 'see the package'}. */`);
  out.push(`export const ${p.exportName} = ${JSON.stringify(inlineSafe(code))};`);
  out.push(`export const ${p.exportName.replace('_SCRIPT', '_VERSION')} = ${JSON.stringify(pkg.version)};`);
  dts.push(`/** ${p.name}@${pkg.version} (${p.file}), safe to inline in a <script> element. */`);
  dts.push(`export declare const ${p.exportName}: string;`);
  dts.push(`export declare const ${p.exportName.replace('_SCRIPT', '_VERSION')}: string;`);
}

const banner = `// Generated by src/features/auth/captcha/vendor/build.mjs from ${header.join(', ')} - do not edit.\n`;
writeFileSync(path.join(HERE, 'scripts.js'), `${banner}/* eslint-disable */\n${out.join('\n')}\n`);
writeFileSync(path.join(HERE, 'scripts.d.ts'), `${banner}${dts.join('\n')}\n`);
console.log(`captcha vendor scripts written: ${header.join(', ')}`);
